void main_top_read_i8_0(ap_int<1024> *arg0, hls::stream<ap_int<8>> arg1[128])
{
  #pragma HLS INLINE off
  for (size_t idx0 = 0; idx0 < 512; idx0 += 1) {
    #pragma HLS PIPELINE II=1 style=flp
    ap_int<1024> elem_tmp0 = arg0[idx0];
    for (size_t idx1 = 0; idx1 < 128; idx1 += 1) {
      arg1[idx1].write(elem_tmp0.range((idx1 + 1) * 8 - 1, idx1 * 8));
    }
  }
}
